import csv, datetime as dt, calendar
from collections import defaultdict
base='/app/dataset'
emps={r['PESEL']:r for r in csv.DictReader(open(base+'/employees.csv'))}
rows=list(csv.DictReader(open(base+'/timesheet.csv')))
# exact dedupe before? include invalid date unique
seen=set(); ded=[]
for r in rows:
    key=tuple((k,r[k]) for k in r if k!='id')
    if key not in seen:
        seen.add(key); ded.append(r)

def parse_roll(s):
    y,m,d=map(int,s.split('-'))
    base=dt.date(y,m,1)
    return base+dt.timedelta(days=d-1)

def parse_clamp(s):
    y,m,d=map(int,s.split('-'))
    try: return dt.date(y,m,d)
    except ValueError: return dt.date(y,m,calendar.monthrange(y,m)[1])

def invalid(s):
    try: dt.date.fromisoformat(s); return False
    except: return True

bad=[r for r in ded if invalid(r['date'])]
