    eid=r['employee_id']; rate=float(emps[eid]['hourly_rate']) if eid in emps else None
    print('\nrow',r['id'],r['date'],'roll',parse_roll(r['date']),'clamp',parse_clamp(r['date']),'eid',eid,'rate',rate,'hrs',r['hours_worked'],'sal',r['salary_amount'],'tasks',r['performed_tasks'],'bonus',r['bonus'])
    if rate:
        # show same emp rows +/- 5 days under roll actual valid dates
        for mode,parse in [('clamp',parse_clamp),('roll',parse_roll)]:
            d=parse(r['date'])
            neigh=[]
